class PitchShifterProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [{
      name: 'ratio',
      defaultValue: 1,
      minValue: 0.25,
      maxValue: 4,
      automationRate: 'k-rate'
    }];
  }

  constructor() {
    super();
    this.BUF = 16384;
    this.GRAIN = 2048;
    this.HOP = this.GRAIN / 2;
    this.DELAY = this.GRAIN * 2; // safe for ratios up to 2x

    this.ringBuffers = [];
    this.writePos = 0;

    // Two grain readers, offset by HOP in phase for seamless crossfade.
    this.grains = [
      { pos: 0, phase: 0 },
      { pos: 0, phase: this.HOP }
    ];
    this.resetGrain(0);
    this.resetGrain(1);
    this.grains[1].phase = this.HOP;
  }

  resetGrain(g) {
    this.grains[g].pos = (this.writePos - this.DELAY + this.BUF) % this.BUF;
    this.grains[g].phase = 0;
  }

  hann(phase) {
    return 0.5 * (1 - Math.cos(2 * Math.PI * phase / this.GRAIN));
  }

  process(inputs, outputs, parameters) {
    const input = inputs[0];
    const output = outputs[0];
    if (!output || output.length === 0) return true;

    const numCh = output.length;
    const frameLen = output[0].length;
    const ratio = parameters.ratio[0];

    // Ensure ring buffers exist
    while (this.ringBuffers.length < numCh) {
      this.ringBuffers.push(new Float32Array(this.BUF));
    }

    for (let i = 0; i < frameLen; i++) {
      // Write input to ring buffer
      for (let ch = 0; ch < numCh; ch++) {
        const inCh = input && input[ch];
        this.ringBuffers[ch][this.writePos] = inCh ? inCh[i] : 0;
      }

      // Read output from two overlapping grains
      for (let ch = 0; ch < numCh; ch++) {
        const buf = this.ringBuffers[ch];
        let s = 0;
        for (let g = 0; g < 2; g++) {
          const grain = this.grains[g];
          const w = this.hann(grain.phase);
          const idx = Math.floor(grain.pos);
          const frac = grain.pos - idx;
          const sample = buf[idx % this.BUF] * (1 - frac) +
                         buf[(idx + 1) % this.BUF] * frac;
          s += sample * w;
        }
        output[ch][i] = s;
      }

      // Advance grain readers at the pitch ratio
      for (let g = 0; g < 2; g++) {
        const grain = this.grains[g];
        grain.pos = (grain.pos + ratio) % this.BUF;
        grain.phase += 1;
        if (grain.phase >= this.GRAIN) {
          this.resetGrain(g);
        }
      }

      this.writePos = (this.writePos + 1) % this.BUF;
    }

    return true;
  }
}
registerProcessor('pitch-shifter', PitchShifterProcessor);
